function setOpen(e,t){e.classList.toggle("is-open",t),e.querySelector(".eba-tabs__toggle").setAttribute("aria-expanded",t?"true":"false")}document.addEventListener("click",function(e){let t=e.target.closest(".eba-tabs__toggle");document.querySelectorAll(".eba-tabs.is-open").forEach(function(e){t&&e.contains(t)||setOpen(e,!1)}),t&&setOpen(e=t.closest(".eba-tabs"),!e.classList.contains("is-open"))}),document.addEventListener("keydown",function(e){"Escape"===e.key&&document.querySelectorAll(".eba-tabs.is-open").forEach(function(e){setOpen(e,!1),e.querySelector(".eba-tabs__toggle").focus()})});